package org.sleepwell.app;
import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class GoalAlarmPlanStorageTest {
 interface Work{void run(SharedPreferences p)throws Exception;}void fixture(Work work)throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="goal-alarm-plan-"+UUID.randomUUID();SharedPreferences p=c.getSharedPreferences(name,0);SleepPlans.Factory old=SleepPlans.factory;Map<String,?> personal=new HashMap<>(Prefs.of(c).getAll());try{SleepPlans.factory=context->p;work.run(p);}finally{SleepPlans.factory=old;c.deleteSharedPreferences(name);assertEquals(personal,Prefs.of(c).getAll());}}
 @Test public void absentPlanIsNotInventedFromDefaults()throws Exception{fixture(p->{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();try{GoalAlarmPlan.load(c);fail();}catch(IllegalArgumentException expected){}assertTrue(p.getAll().isEmpty());p.edit().putInt("goal",480).commit();try{GoalAlarmPlan.load(c);fail();}catch(IllegalArgumentException expected){}assertFalse(p.contains("bedtime"));});}
 @Test public void legacySavedValuesAreReadOnlyAndRevisionDetectsLaterChanges()throws Exception{fixture(p->{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();p.edit().putInt("goal",450).putInt("bedtime",1390).putString("goalCommitments","[]").putString("unknown","kept").commit();Map<String,?> original=new HashMap<>(p.getAll());GoalAlarmPlan.Snapshot first=GoalAlarmPlan.load(c);assertEquals(400,first.time().minute);assertEquals(0,first.revision);assertEquals(original,p.getAll());SleepPlan next=SleepPlans.load(c);next.goal=480;next.bedtime=1350;next.wake=390;SleepPlans.save(c,next);GoalAlarmPlan.Snapshot second=GoalAlarmPlan.load(c);assertNotEquals(first.identity(),second.identity());assertEquals(390,second.time().minute);assertEquals("[]",p.getString("goalCommitments",""));assertEquals("kept",p.getString("unknown",""));});}
 @Test public void corruptSavedTypesAndRangesRemainUnchangedOnRejection()throws Exception{fixture(p->{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();p.edit().putInt("bedtime",1350).putString("goal","480").commit();Map<String,?> original=new HashMap<>(p.getAll());try{GoalAlarmPlan.load(c);fail();}catch(IllegalArgumentException expected){}assertEquals(original,p.getAll());p.edit().putInt("goal",480).putLong("planRevision",-1).commit();original=new HashMap<>(p.getAll());try{GoalAlarmPlan.load(c);fail();}catch(IllegalArgumentException expected){}assertEquals(original,p.getAll());});}
}
